/** Window ids in drawn order (by z-index), lowest first. */
function drawnOrder( manager: WindowManager ): string[] {
	return [ ...manager._stack ]
		.sort(
			( a, b ) =>
				Number( a.element.style.zIndex ) - Number( b.element.style.zIndex ),
		)
		.map( ( w ) => w.id );
}

describe( 'keep on top', () => {
	let desktop: HTMLElement;
	let manager: WindowManager;

	beforeEach( () => {
		installHooksStub();
		desktop = makeDesktop();
		document.body.appendChild( desktop );
		manager = new WindowManager( desktop );
	} );

	afterEach( () => {
		for ( const w of manager.getAll() ) {
			w.destroy();
		}
		desktop.remove();
		clearHooksStub();
	} );

	test( 'a pinned window stays drawn above focused and newly opened windows', async () => {
		const pinned = await manager.open( cfg( 'pinned' ) );
		const other = await manager.open( cfg( 'other' ) );
		pinned.toggleAlwaysOnTop();
		expect( pinned.alwaysOnTop ).toBe( true );

		manager.focus( other );
		const later = await manager.open( cfg( 'later' ) );

		// Focus moves as usual; only the drawing order is constrained.
		expect( later.isFocused() ).toBe( true );
		expect( manager.getFocused() ).toBe( later );
		expect( drawnOrder( manager ).at( -1 ) ).toBe( 'pinned' );
	} );

	test( 'pinned windows stack in focus order among themselves, and unpinning restores normal stacking', async () => {
		await manager.open( cfg( 'a' ) );
		await manager.open( cfg( 'b' ) );
		await manager.open( cfg( 'c' ) );
		manager.setAlwaysOnTop( 'a', true );
		manager.setAlwaysOnTop( 'b', true );

		manager.focus( 'a' );
		manager.focus( 'c' );
		expect( drawnOrder( manager ) ).toEqual( [ 'c', 'b', 'a' ] );

		manager.setAlwaysOnTop( 'a', false );
		expect( drawnOrder( manager ) ).toEqual( [ 'a', 'c', 'b' ] );
		manager.setAlwaysOnTop( 'b', false );
		expect( drawnOrder( manager ) ).toEqual( zOrder( manager ) );
	} );

	test( 'a child is never drawn under an owner that is kept on top', async () => {
		await manager.open( cfg( 'owner' ) );
		await manager.openChild( 'owner', cfg( 'child' ) );
		await manager.open( cfg( 'other' ) );

		manager.setAlwaysOnTop( 'owner', true );

		expect( drawnOrder( manager ) ).toEqual( [ 'other', 'owner', 'child' ] );
	} );

	test( 'only a real change fires the change event', async () => {
		await manager.open( cfg( 'w' ) );
		const seen = vi.fn();
		document.addEventListener( 'os-window-always-on-top-changed', seen );

		manager.setAlwaysOnTop( 'w', true );
		manager.setAlwaysOnTop( 'w', true );
		manager.setAlwaysOnTop( 'missing', true );

		document.removeEventListener( 'os-window-always-on-top-changed', seen );
		expect( seen ).toHaveBeenCalledTimes( 1 );
		expect( ( seen.mock.calls[ 0 ][ 0 ] as CustomEvent ).detail ).toEqual( {
			windowId: 'w',
			alwaysOnTop: true,
		} );
	} );

	test( 'survives a session round-trip', async () => {
		const origin = window.location.origin;
		const url = ( id: string ) => `${ origin }/wp-admin/${ id }.php`;
		await manager.open( cfg( 'pinned', { url: url( 'pinned' ) } ) );
		await manager.open( cfg( 'plain', { url: url( 'plain' ) } ) );
		manager.setAlwaysOnTop( 'pinned', true );

		const session = manager.snapshot();
		expect(
			session.windows.map( ( w ) => [ w.id, w.alwaysOnTop ?? false ] ),
		).toEqual( [ [ 'pinned', true ], [ 'plain', false ] ] );

		for ( const w of manager.getAll() ) {
			w.destroy();
		}
		const restored = new WindowManager( desktop );
		await restoreSession(
			restored,
			{
				adminUrl: `${ origin }/wp-admin/`,
				dockItems: [],
				session,
			} as unknown as DesktopConfig,
			desktop,
		);

		expect( restored.getById( 'pinned' )?.alwaysOnTop ).toBe( true );
		expect( restored.getById( 'plain' )?.alwaysOnTop ).toBe( false );
		expect( drawnOrder( restored ).at( -1 ) ).toBe( 'pinned' );
		manager = restored;
	} );
} );
